/* ---------- films: the vine, annual cycle, growing environment ---------- */
FILMS.push(
{id:"vine",sec:"v",ch:"vig",ic:"grapes",t:I3("La vite: specie, varietà, cloni e innesti","La vigne : espèces, cépages, clones et greffage","The vine: species, varieties, clones and grafting"),s:[
 {h:I3("Le specie di vite","Les espèces de vigne","Vine species"),
  c:I3("Esistono molte specie di vite, ma ai viticoltori ne interessano poche. Vitis vinifera è la specie euroasiatica: produce quasi tutte le uve da vino. Le specie americane danno vini dai sapori poco gradevoli, ma resistono alla fillossera e per questo si usano come portinnesti.",
   "Il existe de nombreuses espèces de vigne, mais peu intéressent les viticulteurs. Vitis vinifera est l'espèce eurasienne : elle produit presque tous les raisins de cuve. Les espèces américaines donnent des vins aux arômes peu agréables, mais elles résistent au phylloxéra et servent donc de porte-greffes.",
   "There are many vine species, but growers care about only a few. Vitis vinifera is the Eurasian species: it produces nearly all wine grapes. American species give wines with unattractive flavours, but they resist phylloxera, so they are used as rootstocks."),
  v:()=>fSvg(fGround()+`<g transform="translate(-70 0)">${vForm("headspur","canopy",160,172)}</g><g transform="translate(80 0)">${vForm("headspur","canopy",160,172)}</g>`+fRoots(90,172)+fRoots(240,172)+fChip(90,24,"Vitis vinifera")+fChip(240,24,w3("Specie americane","Espèces américaines","American species"))+fD(1.5,fCall(240,190,250,150,w3("radici resistenti","racines résistantes","resistant roots"),0,"#86b85a")),"spring")},
 {h:I3("Varietà: talea e propaggine","Cépages : bouture et marcottage","Varieties: cuttings and layering"),
  c:I3("Una varietà non si riproduce dal seme, che darebbe una pianta diversa. Si usa la talea, un tratto di tralcio piantato che mette radici, oppure la propaggine: un tralcio viene piegato e interrato, radica e poi viene staccato dalla pianta madre. La nuova pianta è identica all'originale. Oggi si preferisce la talea, per il rischio di fillossera.",
   "Un cépage ne se reproduit pas par semis, qui donnerait une plante différente. On utilise la bouture, un morceau de rameau planté qui s'enracine, ou le marcottage : un sarment est courbé et enterré, il s'enracine puis on le sépare de la plante mère. La nouvelle plante est identique à l'originale. Aujourd'hui on préfère la bouture, à cause du phylloxéra.",
   "A variety is not grown from seed, which would give a different plant. Growers use cuttings, a section of shoot planted to grow roots, or layering: a cane is bent down and buried, it roots and is then cut from the mother vine. The new plant is identical to the original. Cuttings are now preferred because of the phylloxera risk."),
  v:()=>fSvg(fGround()+`<g transform="translate(-60 0)">${vForm("headspur","canopy",120,172)}</g><path d="M66 112Q120 70 150 172" stroke="#7a5236" stroke-width="2.6" fill="none"/><path d="M150 172Q156 160 162 120" stroke="#6f8f3a" stroke-width="2" fill="none"/>${fLeaf(162,124,.8,10)}`+fD(1,fRoots(150,174))+fD(2.4,`<path d="M118 92l10 10M128 92l-10 10" stroke="#e8dccf" stroke-width="2.4"/>`)+`<g transform="translate(250 0)"><path d="M0 172V132" stroke="#7a5236" stroke-width="3"/>${fLeaf(2,134,.7,15)}${fD(.8,fRoots(0,172))}</g>`+fChip(110,30,w3("propaggine","marcottage","layering"))+fChip(250,30,w3("talea","bouture","cutting")),"spring")},
 {h:I3("I cloni","Les clones","Clones"),
  c:I3("Tutte le piante di una varietà sono geneticamente identiche, ma durante la crescita possono comparire mutazioni. Se sono positive, migliore qualità o resistenza, si moltiplicano quelle piante: è la selezione clonale. Alcune mutazioni sono così forti da diventare varietà a sé: Pinot Blanc e Pinot Gris sono mutazioni del Pinot Noir.",
   "Toutes les plantes d'un cépage sont génétiquement identiques, mais des mutations peuvent apparaître pendant la croissance. Si elles sont positives, meilleure qualité ou résistance, on multiplie ces plantes : c'est la sélection clonale. Certaines mutations sont si marquées qu'elles deviennent des cépages à part : le Pinot Blanc et le Pinot Gris sont des mutations du Pinot Noir.",
   "All the plants of a variety are genetically identical, but mutations can appear as vines grow. If they are positive, better quality or disease resistance, those plants are propagated: this is clonal selection. Some mutations are so marked that they become varieties of their own: Pinot Blanc and Pinot Gris are mutations of Pinot Noir."),
  v:()=>fSvg(fBunch(160,40,2.2,"#3d1a3a")+fT(160,30,"Pinot Noir",11)+[["#b98a9a",80,"Pinot Gris"],["#d8e08a",240,"Pinot Blanc"]].map(([c,x,l],i)=>fD(.8+i*.6,fArrow(`M160 92Q${(160+x)/2} 110 ${x} 120`,null,1)+fBunch(x,130,1.6,c)+fT(x,186,l,11))).join(""))},
 {h:I3("Creare nuove varietà","Créer de nouveaux cépages","Creating new varieties"),
  c:I3("Per ottenere varietà nuove si usa la fecondazione incrociata: il polline di un fiore viene portato sul fiore di un'altra vite. Il seme che nasce è una varietà nuova, con un patrimonio genetico diverso dai genitori, e non si sa in anticipo quali qualità avrà. Servono centinaia di semi e anni di prove: per questo poche varietà moderne hanno avuto successo.",
   "Pour obtenir de nouveaux cépages, on pratique la fécondation croisée : le pollen d'une fleur est déposé sur la fleur d'une autre vigne. La graine obtenue est un cépage nouveau, au patrimoine génétique différent de ses parents, et on ne sait pas à l'avance quelles qualités il aura. Il faut des centaines de graines et des années d'essais : c'est pourquoi peu de cépages modernes ont réussi.",
   "New varieties are created by cross-fertilisation: pollen from one vine's flower is transferred to another vine's flower. The resulting seed is a new variety, genetically different from its parents, and nobody knows in advance what qualities it will have. It takes hundreds of seeds and years of trials, which is why few modern varieties have succeeded."),
  v:()=>fSvg([70,250].map(x=>`<g transform="translate(${x} 70)">${[0,1,2,3,4,5,6].map(k=>`<circle cx="${(k%3-1)*7}" cy="${Math.floor(k/3)*7}" r="3.4" fill="#f2ecc0"/>`).join("")}</g>`).join("")+Array.from({length:6},(_,i)=>`<circle r="1.8" fill="#f6c75a"><animateMotion dur="2s" begin="${i*.3}s" repeatCount="indefinite" path="M70 70Q160 20 250 70"/></circle>`).join("")+fD(1.6,`<ellipse cx="160" cy="130" rx="6" ry="9" fill="#8a5a33"/>`+fArrow("M160 142V160")+`<path d="M160 190V170" stroke="#6f8f3a" stroke-width="2"/>${fLeaf(160,172,.7,0)}`)+fChip(160,112,w3("seme = nuova varietà","graine = nouveau cépage","seed = new variety"),"#d4a23a","#2a1b20"))},
 {h:I3("Incroci e ibridi","Croisements et hybrides","Crossings and hybrids"),
  c:I3("Un incrocio nasce da due genitori della stessa specie: per esempio il Müller-Thurgau, Riesling per Madeleine Royale, e il Pinotage, Pinot Noir per Cinsault. Anche il Cabernet Sauvignon è un incrocio naturale di Cabernet Franc e Sauvignon Blanc. Un ibrido ha genitori di specie diverse, di solito almeno una americana: raramente se ne fa vino, con eccezioni come il Vidal in Canada, ma sono fondamentali come portinnesti.",
   "Un croisement naît de deux parents de la même espèce : par exemple le Müller-Thurgau, Riesling par Madeleine Royale, et le Pinotage, Pinot Noir par Cinsault. Le Cabernet Sauvignon lui-même est un croisement naturel de Cabernet Franc et de Sauvignon Blanc. Un hybride a des parents d'espèces différentes, en général au moins une américaine : on en fait rarement du vin, sauf exceptions comme le Vidal au Canada, mais ils sont essentiels comme porte-greffes.",
   "A crossing comes from two parents of the same species: for example Müller-Thurgau, Riesling × Madeleine Royale, and Pinotage, Pinot Noir × Cinsault. Even Cabernet Sauvignon is a natural crossing of Cabernet Franc and Sauvignon Blanc. A hybrid has parents from different species, usually at least one American: they are rarely used for wine, with exceptions such as Vidal in Canada, but they are vital as rootstocks."),
  v:()=>fSvg(fT(160,22,w3("Incroci (stessa specie)","Croisements (même espèce)","Crossings (same species)"),11,"#f3cd8a")+[["Riesling × Madeleine Royale","Müller-Thurgau"],["Pinot Noir × Cinsault","Pinotage"],["Cab. Franc × Sauv. Blanc","Cabernet Sauvignon"]].map(([a,b],i)=>fD(.4+i*.5,fBox(14,32+i*28,170,22,a)+fArrow(`M188 ${43+i*28}H206`)+fBox(210,32+i*28,98,22,b,{fill:"rgba(140,29,64,.6)"}))).join("")+fD(2.2,fT(160,132,w3("Ibridi (specie diverse)","Hybrides (espèces différentes)","Hybrids (different species)"),11,"#f3cd8a")+fBox(14,142,170,22,"V. vinifera × "+w3("vite americana","vigne américaine","American vine"))+fArrow("M188 153H206")+fBox(210,142,98,22,w3("Vidal · portinnesti","Vidal · porte-greffes","Vidal · rootstocks"),{fill:"rgba(94,140,49,.6)"})))},
 {h:I3("Anatomia: le parti verdi","Anatomie : les parties vertes","Anatomy: the green parts"),
  c:I3("Ogni anno la vite produce i germogli, con foglie, gemme, viticci e fiori. Le foglie sono il motore della pianta: con la fotosintesi trasformano acqua e anidride carbonica in glucosio e ossigeno. Le gemme si formano all'attacco della foglia e contengono in miniatura il germoglio dell'anno dopo. I viticci si avvolgono ai fili per sostenere il germoglio, e i fiori, riuniti in infiorescenze, diventeranno il grappolo.",
   "Chaque année la vigne produit des rameaux, avec feuilles, bourgeons, vrilles et fleurs. Les feuilles sont le moteur de la plante : par la photosynthèse elles transforment eau et gaz carbonique en glucose et oxygène. Les bourgeons se forment à l'aisselle de la feuille et contiennent en miniature le rameau de l'année suivante. Les vrilles s'enroulent autour des fils pour soutenir le rameau, et les fleurs, groupées en inflorescences, deviendront la grappe.",
   "Each year the vine grows shoots carrying leaves, buds, tendrils and flowers. Leaves are the plant's engine: through photosynthesis they turn water and carbon dioxide into glucose and oxygen. Buds form where the leaf joins the shoot and contain next year's shoot in miniature. Tendrils wind around the wires to support the shoot, and the flowers, grouped in inflorescences, will become the bunch."),
  v:()=>fSvg(`<path d="M60 190C80 150 120 110 170 80C210 56 250 40 290 30" stroke="#6f8f3a" stroke-width="4" fill="none"/>`+fLeaf(130,104,2,-30)+fLeaf(220,56,1.7,-10)+`<circle cx="170" cy="80" r="4" fill="#9cc65a"/><path d="M250 44q10 -10 0 -16q-8 -6 2 -12" stroke="#7fa83a" stroke-width="1.6" fill="none"/>`+`<g transform="translate(100 130)">${[0,1,2,3,4,5,6,7].map(k=>`<circle cx="${(k%3-1)*5}" cy="${Math.floor(k/3)*5}" r="2.4" fill="#e6e2a8"/>`).join("")}</g>`+fCall(130,96,70,40,w3("foglia: fotosintesi","feuille : photosynthèse","leaf: photosynthesis"),.3)+fCall(170,80,200,120,w3("gemma","bourgeon","bud"),1)+fCall(252,30,280,80,w3("viticcio","vrille","tendril"),1.7)+fCall(100,134,60,170,w3("infiorescenza","inflorescence","inflorescence"),2.4),"spring")},
 {h:I3("Legno di un anno, legno permanente e radici","Bois d'un an, bois permanent et racines","One-year-old wood, permanent wood and roots"),
  c:I3("In inverno i germogli lignificano e diventano legno di un anno: la vite fruttifica solo sui germogli nati dalle gemme dell'anno prima. Con la potatura si lascia un capo a frutto, lungo, con 8–20 gemme, o uno sperone, corto, con 2–3 gemme. Il legno permanente, più vecchio di un anno, è il tronco con gli eventuali bracci o cordoni. Le radici assorbono acqua e nutrienti, ancorano la pianta e conservano le riserve per l'inverno.",
   "En hiver les rameaux s'aoûtent et deviennent du bois d'un an : la vigne ne fructifie que sur les rameaux issus des bourgeons de l'année précédente. À la taille, on garde une baguette, longue, de 8 à 20 bourgeons, ou un courson, court, de 2 à 3 bourgeons. Le bois permanent, de plus d'un an, est le tronc avec ses éventuels bras ou cordons. Les racines absorbent eau et nutriments, ancrent la plante et stockent les réserves pour l'hiver.",
   "In winter shoots turn woody and become one-year-old wood: vines only fruit on shoots that grow from buds formed the previous year. At pruning the grower keeps a cane, long, with 8 to 20 buds, or a spur, short, with 2 to 3 buds. Permanent wood, more than one year old, is the trunk plus any arms or cordons. Roots absorb water and nutrients, anchor the vine and store reserves for winter."),
  v:()=>fSvg(fGround()+vForm("cordon","bare",160,172)+fRoots(160,174)+fCall(160,140,60,130,w3("tronco","tronc","trunk"),.3)+fCall(220,111,270,96,w3("cordone","cordon","cordon"),1)+fCall(184,104,210,64,w3("sperone 2–3 gemme","courson 2–3 bourgeons","spur 2–3 buds"),1.7)+fCall(160,196,90,190,w3("radici","racines","roots"),2.4),"winter")},
 {h:I3("La fillossera","Le phylloxéra","Phylloxera"),
  c:I3("La fillossera è un insetto nordamericano contro cui Vitis vinifera non ha difese. Arrivata in Europa nell'Ottocento, distrusse i vigneti. In una fase della sua vita vive sottoterra e si nutre delle radici: dalle ferite entrano infezioni e in pochi anni la vite muore. Le viti americane le ostruiscono la bocca con una linfa appiccicosa e isolano le ferite. Oggi è presente quasi ovunque; fanno eccezione il Cile, parte dell'Argentina e l'Australia Meridionale, protetti dalla quarantena.",
   "Le phylloxéra est un insecte nord-américain contre lequel Vitis vinifera n'a aucune défense. Arrivé en Europe au XIXe siècle, il a détruit les vignobles. À une phase de sa vie il vit sous terre et se nourrit des racines : des infections entrent par les blessures et la vigne meurt en quelques années. Les vignes américaines lui bouchent la bouche avec une sève collante et isolent les plaies. Il est aujourd'hui presque partout ; exceptions : le Chili, une partie de l'Argentine et l'Australie-Méridionale, protégés par la quarantaine.",
   "Phylloxera is a North American insect against which Vitis vinifera has no defence. Introduced to Europe in the nineteenth century, it destroyed the vineyards. In one phase of its life it lives underground feeding on the roots: infections enter through the wounds and within a few years the vine dies. American vines clog its mouth with sticky sap and seal off the wounds. It is now almost everywhere; exceptions include Chile, parts of Argentina and South Australia, protected by quarantine."),
  v:()=>fSvg(fGround()+`<rect x="0" y="174" width="320" height="26" fill="#5a4030"/>`+vForm("headspur","canopy",160,172)+fRoots(160,174,1)+[0,1,2,3,4].map(i=>fBug(140+i*9,186+(i%2)*6,"#e8c35a")).join("")+fD(2.5,[100,148,196].map(x=>fLeaf(x,70,1,0,"#c9a441")).join(""))+fChip(160,22,w3("radici attaccate","racines attaquées","roots under attack"),"#b5334a"),"summer")},
 {h:I3("I portinnesti","Les porte-greffes","Rootstocks"),
  c:I3("La fillossera non si combatte con prodotti chimici. La soluzione, alla fine dell'Ottocento, fu innestare Vitis vinifera su radici di viti americane o ibridi: la protezione della vite americana con il gusto della vite europea. I portinnesti offrono anche altri vantaggi, come la resistenza ai nematodi o alla siccità, e si usano persino dove la fillossera non c'è.",
   "Le phylloxéra ne se combat pas par la chimie. La solution, à la fin du XIXe siècle, fut de greffer Vitis vinifera sur des racines de vignes américaines ou d'hybrides : la protection de la vigne américaine avec le goût de la vigne européenne. Les porte-greffes offrent d'autres avantages, comme la résistance aux nématodes ou à la sécheresse, et on les utilise même là où le phylloxéra est absent.",
   "Phylloxera cannot be controlled with chemicals. The solution, found at the end of the nineteenth century, was to graft Vitis vinifera onto roots of American vines or hybrids: the protection of the American vine with the flavour of the European one. Rootstocks also offer other benefits, such as resistance to nematodes or drought, and are used even where phylloxera is absent."),
  v:()=>fSvg(fGround()+vForm("headspur","canopy",160,172)+`<rect x="150" y="150" width="20" height="5" fill="#d4a23a"/>`+fRoots(160,174)+fCall(170,120,240,90,"V. vinifera",.4,"#86b85a")+fCall(170,152,250,140,w3("punto d'innesto","point de greffe","graft union"),1.2)+fCall(166,186,240,186,w3("portinnesto americano","porte-greffe américain","American rootstock"),2),"spring")},
 {h:I3("L'innesto al banco","Le greffage sur table","Bench grafting"),
  c:I3("La tecnica più diffusa è l'innesto al banco, fatto a macchina nei vivai specializzati. Un breve tratto di tralcio della varietà e uno del portinnesto vengono uniti con un incastro e conservati al caldo finché si saldano. La cera rossa protegge il punto d'unione; poi la barbatella è pronta per essere piantata.",
   "La technique la plus courante est le greffage sur table, réalisé à la machine en pépinière. Un court morceau de sarment du cépage et un du porte-greffe sont assemblés par emboîtement et gardés au chaud jusqu'à ce qu'ils se soudent. La cire rouge protège la jonction ; le plant est alors prêt à être planté.",
   "The most common technique is bench grafting, done by machine in specialist nurseries. A short section of cane from the variety and one from the rootstock are joined with an interlocking cut and kept warm until they fuse. Red wax protects the join; the young vine is then ready to plant."),
  v:()=>fSvg(`<g><animateTransform attributeName="transform" type="translate" values="0 -30;0 0;0 0" dur="2.5s" fill="freeze"/><path d="M160 30V96l-8 6 8 6" stroke="#86b85a" stroke-width="10" fill="none" stroke-linejoin="round"/><circle cx="160" cy="44" r="4" fill="#9cc65a"/></g><path d="M160 108V176" stroke="#8a5a33" stroke-width="10"/>`+fD(2.6,`<rect x="148" y="92" width="24" height="22" rx="6" fill="#c0392b"/>`)+fCall(166,50,240,40,"V. vinifera",.2,"#86b85a")+fCall(166,150,240,150,w3("portinnesto","porte-greffe","rootstock"),.8)+fD(2.8,fChip(80,104,w3("cera protettiva","cire protectrice","protective wax"),"#c0392b")))},
 {h:I3("L'innesto in campo","Le surgreffage","Head grafting"),
  c:I3("Se un viticoltore vuole cambiare varietà in un vigneto già impiantato, usa l'innesto in campo: la vite viene tagliata fino al tronco e vi si innesta una gemma o un tralcio della nuova varietà. Se riesce, la vite dà i frutti nuovi già alla vendemmia successiva, mentre una vite appena piantata ne richiede almeno tre. Costa molto meno che reimpiantare e la nuova varietà parte con un apparato radicale già sviluppato.",
   "Si un vigneron veut changer de cépage dans une vigne déjà plantée, il pratique le surgreffage : la vigne est rabattue jusqu'au tronc et on y greffe un bourgeon ou un sarment du nouveau cépage. Si la greffe prend, la vigne produit le nouveau raisin dès la vendange suivante, alors qu'une jeune vigne en demande au moins trois. C'est bien moins cher que replanter et le nouveau cépage profite d'un système racinaire déjà établi.",
   "If a grower wants to switch variety in an established vineyard, they use head grafting: the vine is cut back to its trunk and a bud or cutting of the new variety is grafted on. If it takes, the vine bears the new variety's fruit at the very next vintage, whereas a newly planted vine needs at least three years. It is much cheaper than replanting and the new variety starts with an established root system."),
  v:()=>fSvg(fGround()+vTrunk(110,172,60)+`<rect x="102" y="106" width="16" height="10" fill="#e8dccf"/>`+`<g><animateTransform attributeName="transform" type="scale" from="1 0" to="1 1" dur="2s" fill="freeze" additive="sum"/></g>`+fD(.6,vShoot(110,106,96,60,1,1)+vShoot(110,106,128,58,1,0))+fRoots(110,174)+fD(1.4,fBox(190,40,110,34,w3("innesto in campo: frutti dopo 1 anno","surgreffage : fruits après 1 an","head graft: fruit after 1 year"),{fill:"rgba(94,140,49,.6)"}))+fD(2.2,fBox(190,86,110,34,w3("nuovo impianto: almeno 3 anni","nouvelle plantation : au moins 3 ans","new planting: at least 3 years"))),"spring")}
]},
{id:"cycle",sec:"v",ch:"vig",ic:"grapes",t:I3("Il ciclo annuale e il calendario del vigneto","Le cycle annuel et le calendrier du vignoble","The annual cycle and the vineyard calendar"),s:[
 {h:I3("Dormienza invernale","Dormance hivernale","Winter dormancy"),
  c:I3("Da dicembre a marzo nell'emisfero nord, da luglio a settembre nel sud. I germogli diventano legnosi e prendono il nome di tralci, le foglie cadono e la vite accumula le riserve di carboidrati nelle radici. Nei climi continentali il gelo può uccidere le gemme o la pianta: si rincalza la terra attorno al ceppo. È il periodo della potatura invernale.",
   "De décembre à mars dans l'hémisphère nord, de juillet à septembre dans le sud. Les rameaux deviennent ligneux et prennent le nom de sarments, les feuilles tombent et la vigne stocke ses réserves de glucides dans les racines. En climat continental le gel peut tuer les bourgeons ou la plante : on butte la terre autour du cep. C'est la période de la taille d'hiver.",
   "December to March in the Northern Hemisphere, July to September in the Southern. Shoots turn woody and are now called canes, leaves fall and the vine stores its carbohydrate reserves in the roots. In continental climates winter freeze can kill buds or the vine itself: earth is piled up around the trunk. This is when winter pruning takes place."),
  v:()=>fSvg(fSnow()+fGround("#e9eef2")+fVine("pruned")+fChip(64,26,w3("dic–mar · lug–set","déc–mars · juil–sept","Dec–Mar · Jul–Sep")),"winter")},
 {h:I3("Germogliamento","Débourrement","Budburst"),
  c:I3("A marzo–aprile nel nord, settembre–ottobre nel sud. Le gemme si gonfiano e si aprono quando la temperatura media giornaliera supera circa 10 °C. Chardonnay e Pinot Noir germogliano presto, con temperature basse; il Cabernet Sauvignon è tardivo. Le gelate primaverili possono uccidere i germogli, soprattutto delle varietà precoci. Iniziano, se previsti, i trattamenti contro malattie e parassiti.",
   "En mars–avril au nord, septembre–octobre au sud. Les bourgeons gonflent et s'ouvrent quand la température moyenne journalière dépasse environ 10 °C. Chardonnay et Pinot Noir débourrent tôt, à basse température ; le Cabernet Sauvignon est tardif. Les gelées de printemps peuvent tuer les jeunes pousses, surtout des cépages précoces. Les traitements contre maladies et ravageurs commencent, le cas échéant.",
   "March to April in the north, September to October in the south. Buds swell and burst once the mean daily temperature rises above about 10 °C. Chardonnay and Pinot Noir bud early, at low temperatures; Cabernet Sauvignon buds late. Spring frosts can kill new shoots, especially on early-budding varieties. Spraying against diseases and pests, if practised, begins now."),
  v:()=>fSvg(fSun(280,36,12)+fGround()+fVine("bud")+fThermo(28,72,"10 °C",.35)+fD(2.5,fChip(160,26,w3("precoci: Chardonnay, Pinot Noir","précoces : Chardonnay, Pinot Noir","early: Chardonnay, Pinot Noir"))),"spring")},
 {h:I3("Prima crescita dei germogli","Croissance des rameaux","Early shoot and leaf growth"),
  c:I3("Fino alla fioritura i germogli crescono velocemente: all'inizio con le riserve accumulate in inverno, poi, quando le foglie maturano, con la fotosintesi. In questa fase la vite ha bisogno di acqua e nutrienti a sufficienza. I germogli vengono legati alla spalliera perché la chioma resti aperta, e i trattamenti continuano.",
   "Jusqu'à la floraison, les rameaux poussent vite : d'abord grâce aux réserves de l'hiver, puis, quand les feuilles sont mûres, grâce à la photosynthèse. La vigne a alors besoin de suffisamment d'eau et de nutriments. On attache les rameaux au palissage pour garder un feuillage aéré, et les traitements continuent.",
   "Shoots grow rapidly until flowering: at first fuelled by the reserves stored over winter, then by photosynthesis as the leaves mature. The vine needs a good supply of water and nutrients at this stage. Shoots are tied to the trellis to keep the canopy open, and spraying continues."),
  v:()=>fSvg(fSun(280,36,12)+fGround()+fVine("shoot")+fD(2,fArrow("M30 190C40 160 60 140 90 120",null,1)+fChip(54,150,w3("riserve","réserves","reserves")))+fD(2.6,fChip(250,70,w3("fotosintesi","photosynthèse","photosynthesis"),"#5e8c31")),"spring")},
 {h:I3("Fioritura e allegagione","Floraison et nouaison","Flowering and fruit set"),
  c:I3("A maggio–giugno nel nord, novembre–dicembre nel sud. Per la fioritura servono caldo, sole e poca pioggia, altrimenti l'impollinazione si interrompe. Con l'allegagione il fiore inizia a diventare acino; i fiori non fecondati cadono. Se ne cadono più del normale si parla di colatura; se gli acini restano piccoli e senza semi, di acinellatura. Entrambe riducono le rese e dipendono da tempo freddo, nuvoloso o piovoso.",
   "En mai–juin au nord, novembre–décembre au sud. La floraison demande chaleur, soleil et peu de pluie, sinon la pollinisation est perturbée. À la nouaison la fleur commence à devenir baie ; les fleurs non fécondées tombent. S'il en tombe plus que d'habitude, c'est la coulure ; si des baies restent petites et sans pépins, c'est le millerandage. Les deux réduisent les rendements et viennent d'un temps froid, nuageux ou pluvieux.",
   "May to June in the north, November to December in the south. Flowering needs warmth, sunshine and little or no rain, otherwise pollination is disrupted. At fruit set the flower starts to become a berry; unpollinated flowers drop off. If more flowers than normal fail, this is coulure; if berries form without seeds and stay small, this is millerandage. Both reduce yields and stem from cold, cloudy or rainy weather."),
  v:()=>fSvg(fSun(280,36,13)+fGround()+fVine("flower")+fD(2,`<g transform="translate(60 120)">${fBunch(0,0,1.6,"#9cc65a")}</g>`+fChip(60,108,w3("colatura","coulure","coulure"),"#b5334a"))+fD(3,`<g transform="translate(262 120)">${[0,1,2,3,4,5,6].map(k=>`<circle cx="${(k%3-1)*7}" cy="${Math.floor(k/3)*7}" r="${k%2?2:4}" fill="#9cc65a"/>`).join("")}</g>`+fChip(262,108,w3("acinellatura","millerandage","millerandage"),"#b5334a")),"spring")},
 {h:I3("Gli acini crescono, ancora verdi","Les baies grossissent, encore vertes","Berries grow, still green"),
  c:I3("Dopo l'allegagione, per sei–otto settimane gli acini crescono. In questa fase sia le uve nere sia le bianche sono verdi e dure al tatto, con molta acidità e quasi niente zucchero.",
   "Après la nouaison, les baies grossissent pendant six à huit semaines. À ce stade, raisins noirs et blancs sont verts et durs au toucher, très acides et presque sans sucre.",
   "After fruit set the berries grow for six to eight weeks. At this stage both black and white grapes are green and hard to the touch, high in acid and with almost no sugar."),
  v:()=>fSvg(fSun(280,34,14)+fGround()+fVine("set")+fClock(40,50,w3("6–8 settimane","6–8 semaines","6–8 weeks")),"summer")},
 {h:I3("Invaiatura","Véraison","Véraison"),
  c:I3("Da luglio a settembre nel nord, da gennaio a marzo nel sud. L'invaiatura segna l'inizio della maturazione: le bucce cambiano colore. Le uve nere diventano prima rosse e poi viola; le bianche diventano traslucide e dorate.",
   "De juillet à septembre au nord, de janvier à mars au sud. La véraison marque le début de la maturation : les peaux changent de couleur. Les raisins noirs deviennent rouges puis violets ; les blancs deviennent translucides et dorés.",
   "July to September in the north, January to March in the south. Véraison marks the start of ripening: the skins change colour. Black grapes turn red, then purple; white grapes become translucent and golden."),
  v:()=>fSvg(fSun(280,34,15)+fGround()+fVine("ver")+fD(2.5,`<g transform="translate(40 100)">${fBunch(0,0,1.4,["#9cc65a","#e3c76a"],"ver",0)}</g>`+fChip(40,92,w3("bianche","blancs","white"))),"summer")},
 {h:I3("Maturazione","Maturation","Ripening"),
  c:I3("Tra invaiatura e vendemmia gli acini si gonfiano d'acqua, gli zuccheri salgono e l'acidità scende; si accumulano pigmenti e aromi e i tannini si sviluppano. L'ideale è un tempo caldo e soleggiato, con un leggero stress idrico che frena i germogli e favorisce i grappoli. Se serve si fa la potatura verde per tenere aperta la chioma, e a volte il diradamento dei grappoli, poco dopo l'invaiatura, per controllare la resa.",
   "Entre véraison et vendanges, les baies se gorgent d'eau, les sucres montent et l'acidité baisse ; pigments et arômes s'accumulent et les tanins se développent. L'idéal est un temps chaud et ensoleillé, avec un léger stress hydrique qui freine les rameaux et favorise les grappes. Si besoin, on rogne et effeuille pour garder le feuillage aéré, et on pratique parfois la vendange en vert, peu après la véraison, pour contrôler le rendement.",
   "Between véraison and harvest the berries swell with water, sugar rises and acidity falls; colour pigments and flavours build up and tannins develop. Warm, sunny weather is ideal, with mild water stress that slows shoot growth and favours the grapes. Summer pruning keeps the canopy open if needed, and green harvesting, shortly after véraison, may be used to control yield."),
  v:()=>fSvg(`<rect x="34" y="20" width="252" height="150" rx="12" fill="rgba(255,255,255,.75)"/><path d="M58 32V146H270" stroke="#7d6a70" stroke-width="1.6" fill="none"/>
     <path d="M62 136C120 130 170 90 262 56" stroke="#d4a23a" stroke-width="4" fill="none" stroke-dasharray="260" stroke-dashoffset="260"><animate attributeName="stroke-dashoffset" from="260" to="0" dur="3s" begin=".3s" fill="freeze"/></path>
     <path d="M62 52C120 60 170 110 262 128" stroke="#5e8c31" stroke-width="4" fill="none" stroke-dasharray="260" stroke-dashoffset="260"><animate attributeName="stroke-dashoffset" from="260" to="0" dur="3s" begin=".3s" fill="freeze"/></path>
     <path d="M62 140C140 138 200 120 262 100" stroke="#8c1d40" stroke-width="3" fill="none" stroke-dasharray="4 4"/>
     ${fD(2.6,fT(236,48,w3("zuccheri","sucres","sugar"),10,"#a87b1e")+fT(236,142,w3("acidità","acidité","acidity"),10,"#44691f")+fT(236,96,w3("colore, aromi","couleur, arômes","colour, flavour"),9,"#8c1d40"))}${fT(160,162,w3("invaiatura → vendemmia","véraison → vendanges","véraison → harvest"),10,"#7d6a70")}`,"summer")},
 {h:I3("Vendemmia","Vendanges","Harvest"),
  c:I3("Da settembre a ottobre nel nord, da marzo ad aprile nel sud. L'ideale è un periodo asciutto: la pioggia prima della raccolta gonfia gli acini, diluisce il succo e, con l'umidità, aumenta il rischio di marciume. I trattamenti devono essere finiti abbastanza presto da non lasciare residui chimici nel vino. Dopo la vendemmia le foglie cadono e il ciclo ricomincia.",
   "De septembre à octobre au nord, de mars à avril au sud. L'idéal est une période sèche : la pluie avant la récolte fait gonfler les baies, dilue le jus et, avec l'humidité, augmente le risque de pourriture. Les traitements doivent s'arrêter assez tôt pour ne laisser aucun résidu chimique dans le vin. Après les vendanges les feuilles tombent et le cycle recommence.",
   "September to October in the north, March to April in the south. Ideally the harvest period is dry: rain just before picking swells the berries, dilutes the juice and, with the damp, raises the risk of rot. Spraying must finish early enough to leave no harmful residues in the wine. After harvest the leaves fall and the cycle begins again."),
  v:()=>fSvg(fGround()+fVine("autumn")+fCrate(258,166)+`<g>${fBunch(250,96,1.1,"#6b2d5c")}<animateTransform attributeName="transform" type="translate" values="0 0;0 52;0 52" dur="2.4s" repeatCount="indefinite"/></g>`+fChip(70,26,w3("set–ott · mar–apr","sept–oct · mars–avr","Sep–Oct · Mar–Apr")),"autumn")}
]},
{id:"env1",sec:"v",ch:"env",ic:"maps",t:I3("L'ambiente: calore e luce","L'environnement : chaleur et lumière","The environment: heat and sunlight"),s:[
 {h:I3("Le cinque cose di cui ha bisogno la vite","Les cinq besoins de la vigne","The five things a vine needs"),
  c:I3("Per sopravvivere la vite ha bisogno di cinque cose: calore, luce del sole, acqua, nutrienti e anidride carbonica. Con la fotosintesi la foglia combina anidride carbonica e acqua per produrre glucosio e ossigeno; il glucosio, insieme ai nutrienti del suolo, alimenta la crescita e soprattutto la maturazione dell'uva. L'anidride carbonica abbonda sempre: sono gli altri quattro fattori a variare.",
   "Pour survivre la vigne a besoin de cinq choses : chaleur, lumière du soleil, eau, nutriments et gaz carbonique. Par la photosynthèse, la feuille combine gaz carbonique et eau pour produire glucose et oxygène ; le glucose, avec les nutriments du sol, nourrit la croissance et surtout la maturation du raisin. Le gaz carbonique est toujours abondant : ce sont les quatre autres facteurs qui varient.",
   "To survive the vine needs five things: heat, sunlight, water, nutrients and carbon dioxide. Through photosynthesis the leaf combines carbon dioxide and water to make glucose and oxygen; the glucose, with nutrients from the soil, fuels growth and above all grape ripening. Carbon dioxide is always plentiful: it is the other four factors that vary."),
  v:()=>fSvg(fSun(270,36,14)+fGround()+vForm("headspur","canopy",160,172)+fCall(270,40,226,30,w3("calore e luce","chaleur et lumière","heat and light"),.3)+fCall(120,100,40,60,"CO₂",1)+fCall(160,186,80,186,w3("acqua e nutrienti","eau et nutriments","water and nutrients"),1.7)+fD(2.4,fBox(186,62,124,30,w3("CO₂ + acqua → glucosio + O₂","CO₂ + eau → glucose + O₂","CO₂ + water → glucose + O₂"),{fill:"rgba(94,140,49,.75)"})),"summer")},
 {h:I3("Il calore","La chaleur","Heat"),
  c:I3("Sotto i 10 °C fa troppo freddo perché la vite cresca: per questo d'inverno è in riposo e germoglia in primavera. Serve poi abbastanza calore per fioritura, allegagione e maturazione. La quantità di calore della stagione decide quali varietà si possono coltivare: il Riesling prospera in zone fresche dove la Grenache non maturerebbe mai.",
   "En dessous de 10 °C il fait trop froid pour que la vigne pousse : c'est pourquoi elle se repose l'hiver et débourre au printemps. Il faut ensuite assez de chaleur pour la floraison, la nouaison et la maturation. La quantité de chaleur de la saison décide des cépages possibles : le Riesling prospère dans des zones fraîches où la Grenache ne mûrirait jamais.",
   "Below 10 °C it is too cold for the vine to grow: that is why it is dormant in winter and buds in spring. It then needs enough heat for flowering, fruit set and ripening. The amount of heat in the season decides which varieties can be grown: Riesling thrives in cool places where Grenache would never ripen."),
  v:()=>fSvg(fThermo(40,70,"10 °C",.3,"#4fa8a2")+fBox(80,40,100,40,w3("clima fresco: Riesling","climat frais : Riesling","cool: Riesling"),{fill:"rgba(79,168,162,.55)"})+fBox(200,40,100,40,w3("clima caldo: Grenache","climat chaud : Grenache","hot: Grenache"),{fill:"rgba(181,51,74,.6)"})+`<rect x="80" y="110" width="220" height="12" rx="6" fill="url(#heat)"/><defs><linearGradient id="heat"><stop offset="0" stop-color="#4fa8a2"/><stop offset="1" stop-color="#b5334a"/></linearGradient></defs>`+fT(190,140,w3("più calore → più varietà possibili","plus de chaleur → plus de cépages possibles","more heat → more varieties possible"),9.5))},
 {h:I3("La latitudine","La latitude","Latitude"),
  c:I3("La maggior parte dei vigneti si trova tra 30 e 50 gradi di latitudine, a nord e a sud dell'equatore. Più vicino all'equatore fa troppo caldo, più vicino ai poli troppo freddo. All'equatore l'energia del sole è concentrata su una piccola superficie; ai poli la stessa energia si distribuisce su un'area più ampia.",
   "La plupart des vignobles se situent entre 30 et 50 degrés de latitude, au nord et au sud de l'équateur. Plus près de l'équateur il fait trop chaud, plus près des pôles trop froid. À l'équateur l'énergie du soleil est concentrée sur une petite surface ; aux pôles, la même énergie se répartit sur une surface plus grande.",
   "Most vineyards lie between 30 and 50 degrees of latitude, north and south of the Equator. Closer to the Equator it is too hot, closer to the Poles too cold. At the Equator the sun's energy is concentrated on a small area; at the Poles the same energy is spread over a much wider area."),
  v:()=>`<svg class="fsvg" viewBox="0 0 320 200" aria-hidden="true">${fDefs}<rect width="320" height="200" fill="#14203a"/>${fMoon(-50,-50)}<circle cx="200" cy="100" r="80" fill="#3b7fa8"/><path d="M135 62Q200 50 265 62L270 76Q200 64 130 76Z" fill="#5e8c31" opacity=".9"/><path d="M130 124Q200 136 270 124L265 138Q200 150 135 138Z" fill="#5e8c31" opacity=".9"/><path d="M120 100H280" stroke="#f3cd8a" stroke-dasharray="4 3"/>${fT(316,58,"30–50° N",9,"#f3cd8a","end")}${fT(316,150,"30–50° S",9,"#f3cd8a","end")}${[30,60,100,140,170].map((y,i)=>`<path d="M10 ${y}H${200-Math.sqrt(6400-Math.pow(y-100,2))}" stroke="#f8cf5f" stroke-width="${i===2?5:2}" opacity=".8"><animate attributeName="stroke-dasharray" values="0 200;200 0" dur="1.6s" fill="freeze"/></path>`).join("")}${fT(60,190,w3("raggi concentrati all'equatore","rayons concentrés à l'équateur","rays concentrated at the Equator"),9)}</svg>`},
 {h:I3("L'altitudine","L'altitude","Altitude"),
  c:I3("Salendo di quota la temperatura scende. Per questo regioni molto alte, come Cafayate nel nord dell'Argentina, possono coltivare la vite pur essendo vicine all'equatore.",
   "La température baisse avec l'altitude. C'est pourquoi des régions très élevées, comme Cafayate dans le nord de l'Argentine, peuvent cultiver la vigne bien que proches de l'équateur.",
   "Temperatures drop as altitude rises. This is why very high regions, such as Cafayate in northern Argentina, can grow vines even though they are close to the Equator."),
  v:()=>fSvg(`<path d="M0 200L120 40L200 120L250 80L320 200Z" fill="#8a7a6a"/><path d="M100 66L120 40L140 66Z" fill="#fff"/>`+fRows(150,150,250,190,6)+fThermo(40,40,"−",.25,"#4fa8a2")+fThermo(280,110,"+",.8)+fArrow("M60 170L110 60",null,1)+fChip(206,40,"Cafayate"),"summer")},
 {h:I3("Correnti oceaniche e nebbia","Courants océaniques et brouillard","Ocean currents and fog"),
  c:I3("Le grandi correnti spostano acqua calda o fredda e scaldano o rinfrescano le regioni costiere. La corrente di Humboldt al largo del Cile e quella del Benguela al largo del Sudafrica rinfrescano zone che sarebbero troppo calde; la Corrente del Golfo scalda il nord-ovest dell'Europa. Anche la nebbia rinfresca: è decisiva in molte zone della California e nella Valle di Casablanca, in Cile.",
   "Les grands courants transportent de l'eau chaude ou froide et réchauffent ou rafraîchissent les régions côtières. Le courant de Humboldt au large du Chili et celui de Benguela au large de l'Afrique du Sud rafraîchissent des zones qui seraient trop chaudes ; le Gulf Stream réchauffe le nord-ouest de l'Europe. Le brouillard rafraîchit aussi : il est décisif dans de nombreuses zones de Californie et dans la vallée de Casablanca, au Chili.",
   "Major currents move warm or cold water and warm or cool coastal regions. The Humboldt Current off Chile and the Benguela Current off South Africa cool areas that would otherwise be too hot; the Gulf Stream warms north-west Europe. Fog also cools: it is vital in many parts of California and in Chile's Casablanca Valley."),
  v:()=>fSvg(fSea(0,90,130,110)+`<path d="M130 200V90Q200 70 320 80V200Z" fill="#8a9a4a"/>`+fRows(170,110,300,160,7)+fCurrent("M40 196V110","#7fd0f0")+fD(1,fFog(150,92,170))+fChip(60,82,"Humboldt · Benguela","#2b7a75")+fD(2,fCurrent("M120 40H40","#e2622a")+fChip(80,26,w3("Corrente del Golfo: scalda","Gulf Stream : réchauffe","Gulf Stream: warms"),"#b5334a")),"dusk")},
 {h:I3("Suolo ed esposizione","Sol et exposition","Soil and aspect"),
  c:I3("I suoli scuri o ricchi di pietre assorbono e irradiano più calore: nei climi freschi questo aiuta a maturare. I suoli molto umidi invece si scaldano lentamente e possono ritardare il germogliamento. L'esposizione è la direzione in cui guarda il pendio: i vigneti rivolti verso l'equatore, a sud nell'emisfero nord e a nord in quello sud, ricevono più calore, e più il pendio è ripido più l'effetto è forte, come nella Mosella.",
   "Les sols sombres ou caillouteux absorbent et restituent plus de chaleur : en climat frais cela aide à mûrir. Les sols très humides, au contraire, se réchauffent lentement et peuvent retarder le débourrement. L'exposition est la direction vers laquelle regarde la pente : les vignes tournées vers l'équateur, au sud dans l'hémisphère nord et au nord dans l'hémisphère sud, reçoivent plus de chaleur, et plus la pente est raide plus l'effet est fort, comme en Moselle.",
   "Dark or stony soils absorb and re-radiate more heat: in cool climates this helps ripening. Very wet soils, on the other hand, warm up slowly and can delay budburst. Aspect is the direction a slope faces: vineyards facing the Equator, south in the Northern Hemisphere and north in the Southern, receive the most heat, and the steeper the slope the stronger the effect, as in the Mosel."),
  v:()=>fSvg(fSun(60,40,16)+`<path d="M110 200L300 50V200Z" fill="#6b5a45"/>`+fRows(130,190,290,64,9)+fRays(60,40,[[160,160],[205,124],[250,88]])+`<g>${[0,1,2,3,4,5].map(i=>`<ellipse cx="${150+i*24}" cy="${178-i*19}" rx="5" ry="3" fill="#b7aa96"/>`).join("")}</g>`+fD(1.5,[0,1,2].map(i=>`<path d="M${160+i*40} ${170-i*30}q-4 -8 0 -16" stroke="#f6a43a" stroke-width="1.6" fill="none"><animate attributeName="opacity" values="0;1;0" dur="1.6s" begin="${i*.4}s" repeatCount="indefinite"/></path>`).join(""))+fChip(200,30,w3("esposizione a sud (emisfero nord)","exposition sud (hémisphère nord)","south-facing (Northern Hemisphere)")),"summer")},
 {h:I3("Continentalità","Continentalité","Continentality"),
  c:I3("La continentalità è la differenza di temperatura tra il mese più caldo e il più freddo. Mari e laghi si scaldano e si raffreddano più lentamente della terra: d'inverno scaldano l'aria vicina, d'estate la rinfrescano. Le zone vicine all'acqua hanno bassa continentalità, quelle nell'interno estremi più forti. La continentalità determina la lunghezza della stagione e quindi le varietà possibili.",
   "La continentalité est l'écart de température entre le mois le plus chaud et le plus froid. Mers et lacs se réchauffent et se refroidissent plus lentement que la terre : en hiver ils réchauffent l'air voisin, en été ils le rafraîchissent. Les zones proches de l'eau ont une faible continentalité, celles de l'intérieur des extrêmes plus marqués. La continentalité détermine la durée de la saison et donc les cépages possibles.",
   "Continentality is the temperature difference between the hottest and coldest months. Seas and lakes warm up and cool down more slowly than land: in winter they warm the nearby air, in summer they cool it. Areas near water have low continentality, inland regions see bigger extremes. Continentality sets the length of the growing season and so which varieties can grow."),
  v:()=>fSvg(fSea(0,120,100,80)+`<path d="M100 200V120H320V200Z" fill="#8a9a4a"/>`+`<g transform="translate(40 30)">${[[0,40,"#4fa8a2"],[24,60,"#b5334a"]].map(([x,h,c])=>`<rect x="${x}" y="${80-h}" width="16" height="${h}" fill="${c}"/>`).join("")}</g><g transform="translate(240 30)">${[[0,20,"#4fa8a2"],[24,90,"#b5334a"]].map(([x,h,c])=>`<rect x="${x}" y="${80-h}" width="16" height="${h}" fill="${c}"/>`).join("")}</g>`+fChip(58,24,w3("bassa","faible","low"))+fChip(258,24,w3("alta","forte","high"))+fT(160,190,w3("inverno · estate","hiver · été","winter · summer"),9),"dusk")},
 {h:I3("Escursione termica","Amplitude thermique","Diurnal range"),
  c:I3("L'escursione termica è la differenza tra giorno e notte. Le notti fresche rallentano la perdita di aromi e di acidità; le notti calde accelerano la maturazione. In un clima caldo, un vigneto con grande escursione dà vini più freschi e aromatici. L'acqua vicina, anche un fiume, e le nuvole riducono l'escursione: nelle notti serene la temperatura cala più in fretta.",
   "L'amplitude thermique est l'écart entre le jour et la nuit. Les nuits fraîches ralentissent la perte d'arômes et d'acidité ; les nuits chaudes accélèrent la maturation. En climat chaud, une vigne à forte amplitude donne des vins plus frais et aromatiques. L'eau proche, même une rivière, et les nuages réduisent l'amplitude : par nuit claire la température baisse plus vite.",
   "Diurnal range is the difference between day and night temperatures. Cool nights slow the loss of aromas and acidity; warm nights speed up ripening. In a warm climate a vineyard with a large diurnal range gives fresher, more aromatic wines. Nearby water, even a river, and cloud cover reduce the range: on clear nights temperatures fall faster."),
  v:()=>`<svg class="fsvg" viewBox="0 0 320 200" aria-hidden="true">${fDefs}<rect width="160" height="200" fill="#9fd3f0"/><rect x="160" width="160" height="200" fill="#1b2440"/>${fSun(80,50,16)}<circle cx="240" cy="50" r="12" fill="#f3ecd2"/>${fGround()}${fThermo(60,90,"30 °C",.85)}${fThermo(250,90,"12 °C",.25,"#4fa8a2")}${fD(1.5,fChip(160,24,w3("notti fresche: aromi e acidità","nuits fraîches : arômes et acidité","cool nights: aromas and acidity"),"#d4a23a","#2a1b20"))}</svg>`},
 {h:I3("Gelo d'inverno e inverni miti","Gel d'hiver et hivers doux","Winter freeze and mild winters"),
  c:I3("Sotto i −20 °C la vite può essere gravemente danneggiata o uccisa; il punto più a rischio è l'innesto, che si protegge coprendolo di terra. Anche l'eccesso opposto è un problema: senza un vero inverno, come nei climi subtropicali, la vite non riposa, può dare più raccolti l'anno, vive meno e l'uva peggiora. Gli inverni miti fanno inoltre sopravvivere più insetti.",
   "En dessous de −20 °C la vigne peut être gravement endommagée ou tuée ; le point le plus fragile est la greffe, qu'on protège en la recouvrant de terre. L'excès inverse est aussi un problème : sans véritable hiver, comme en climat subtropical, la vigne ne se repose pas, peut donner plusieurs récoltes par an, vit moins longtemps et le raisin est de moindre qualité. Les hivers doux laissent aussi survivre plus d'insectes.",
   "Below −20 °C the vine can be seriously damaged or killed; the graft is most at risk, so it is protected by covering it with earth. The opposite extreme is also a problem: with no real winter, as in subtropical climates, the vine has no dormancy, may crop more than once a year, lives a shorter life and fruit quality suffers. Mild winters also let more insect pests survive."),
  v:()=>fSvg(fSnow()+fGround("#e9eef2")+vForm("headspur","bare",110,172)+`<path d="M90 172Q110 146 130 172Z" fill="#7a5a3c"/>`+fCall(118,160,60,120,w3("innesto rincalzato","greffe buttée","graft earthed up"),.6)+fThermo(250,60,"−20 °C",.05,"#4fa8a2"),"winter")},
 {h:I3("Gelate primaverili e difese","Gelées de printemps et protections","Spring frost and protection"),
  c:I3("Le gelate di primavera avvengono quando aria sotto lo zero ristagna al suolo e gela l'umidità depositata su gemme e germogli: i danni alla resa possono essere enormi. Ci sono quattro difese principali. Le stufe accese nel vigneto muovono l'aria e impediscono al freddo di posarsi. I ventilatori, grandi pale su un palo, portano giù l'aria più calda dall'alto. Gli irrigatori bagnano le viti: l'acqua, gelando, cede calore e protegge i germogli. La quarta è la progettazione del vigneto.",
   "Les gelées de printemps se produisent quand de l'air sous zéro stagne au sol et gèle l'humidité déposée sur bourgeons et pousses : les dégâts sur le rendement peuvent être énormes. Il existe quatre protections principales. Les chaufferettes allumées dans la vigne mettent l'air en mouvement et empêchent le froid de se poser. Les tours antigel, grandes hélices sur un mât, rabattent l'air plus chaud d'en haut. L'aspersion mouille les vignes : l'eau, en gelant, libère de la chaleur et protège les pousses. La quatrième est la conception du vignoble.",
   "Spring frosts happen when sub-zero air collects at ground level and freezes the moisture on buds and shoots: the damage to yields can be enormous. There are four main defences. Heaters lit in the vineyard keep the air moving so the cold cannot settle. Wind machines, large fans on a tower, draw down warmer air from above. Sprinklers spray the vines: as the water freezes it releases heat and protects the shoots. The fourth is vineyard design."),
  v:()=>fSvg(fMoon(290,30)+fGround("#3b3a4a")+fVine("bud")+fHeater(80,170)+fHeater(200,170)+fWindMachine(30,170)+fSprinkler(270,170)+fD(.4,fChip(50,40,w3("ventilatore","tour antigel","wind machine")))+fD(1,fChip(140,150,w3("stufe","chaufferettes","heaters")))+fD(1.6,fChip(270,108,w3("irrigatori","aspersion","sprinklers"))),"night")},
 {h:I3("Il vigneto progettato contro il gelo","Un vignoble conçu contre le gel","Designing out frost"),
  c:I3("L'aria fredda scende verso il punto più basso e l'aria calda sale. Nelle conche circondate da colline il freddo resta intrappolato e il rischio di gelo è alto; a metà pendio l'aria fredda scivola via. Per questo conviene piantare sui pendii, evitare gli avvallamenti e, se serve, allevare la vite più in alto, lontano dall'aria più fredda.",
   "L'air froid descend vers le point le plus bas et l'air chaud monte. Dans les cuvettes entourées de collines, le froid reste piégé et le risque de gel est élevé ; à mi-pente, l'air froid s'écoule. On plante donc sur les pentes, on évite les dépressions et, si besoin, on conduit la vigne plus haut, loin de l'air le plus froid.",
   "Cold air sinks to the lowest point and warm air rises. In hollows surrounded by hills the cold is trapped and frost risk is high; on the middle of a slope cold air drains away. So vineyards are planted on slopes, depressions are avoided and, if needed, vines are trained higher, away from the coldest air."),
  v:()=>fSvg(`<path d="M0 60Q80 70 130 150Q160 175 190 150Q240 70 320 60V200H0Z" fill="#5d6a3a"/>`+fRows(30,80,110,140,5)+fRows(210,140,290,80,5)+`<ellipse cx="160" cy="160" rx="50" ry="16" fill="#9fd3f0" opacity=".6"><animate attributeName="ry" values="10;18;10" dur="3s" repeatCount="indefinite"/></ellipse>`+[0,1,2].map(i=>fArrow(`M${60+i*10} ${90+i*14}Q100 140 140 156`,"#9fd3f0",1)).join("")+fChip(160,186,w3("conca: rischio gelo","cuvette : risque de gel","hollow: frost risk"),"#2b7a75")+fChip(250,70,w3("mezza costa: più sicuro","mi-pente : plus sûr","mid-slope: safer"),"#5e8c31"),"night")},
 {h:I3("Freddo e caldo nella stagione","Froid et chaleur en saison","Cold and heat in the season"),
  c:I3("Una primavera fredda ritarda il germogliamento: la stagione si accorcia e in autunno può mancare il tempo per maturare. Il freddo disturba anche fioritura e allegagione, con raccolti più piccoli. In estate, invece, periodi di caldo estremo rallentano e poi fermano l'attività della vite anche se l'acqua non manca: l'uva non matura bene e, nei casi estremi, la pianta muore.",
   "Un printemps froid retarde le débourrement : la saison raccourcit et en automne le temps peut manquer pour mûrir. Le froid perturbe aussi floraison et nouaison, avec des récoltes plus petites. En été, au contraire, des périodes de chaleur extrême ralentissent puis stoppent l'activité de la vigne même si l'eau ne manque pas : le raisin mûrit mal et, dans les cas extrêmes, la plante meurt.",
   "A cold spring delays budburst: the season is shortened and there may not be enough time to ripen fully in autumn. Cold also disrupts flowering and fruit set, giving smaller crops. In summer, by contrast, prolonged extreme heat slows and then stops all vine activity even when there is enough water: the grapes fail to ripen properly and, in extreme cases, the vine dies."),
  v:()=>`<svg class="fsvg" viewBox="0 0 320 200" aria-hidden="true">${fDefs}<rect width="160" height="200" fill="#c9d3de"/><rect x="160" width="160" height="200" fill="#f6c27a"/>${fGround()}<g transform="translate(-80 0)">${vForm("headspur","bare",160,172)}</g><g transform="translate(80 0)">${vForm("headspur","canopy",160,172)}</g>${fThermo(20,40,"",.15,"#4fa8a2")}${fThermo(290,40,"",.95)}${fChip(80,26,w3("stagione corta","saison courte","short season"))}${fChip(240,26,w3("attività bloccata","activité bloquée","vine shuts down"))}</svg>`},
 {h:I3("La luce del sole","La lumière du soleil","Sunlight"),
  c:I3("Senza luce non c'è fotosintesi: più luce significa più glucosio per crescere e maturare, e fioritura e allegagione migliori. Più ci si allontana dall'equatore, più le giornate estive sono lunghe: aiuta il Riesling a maturare in Germania. Vicino a mari e laghi ci sono più nuvole, ma i vigneti sopra un fiume o un lago possono ricevere la luce riflessa dall'acqua. L'esposizione verso l'equatore massimizza la luce, soprattutto vicino ai poli.",
   "Sans lumière pas de photosynthèse : plus de lumière signifie plus de glucose pour pousser et mûrir, et une meilleure floraison et nouaison. Plus on s'éloigne de l'équateur, plus les journées d'été sont longues : cela aide le Riesling à mûrir en Allemagne. Près des mers et lacs il y a plus de nuages, mais les vignes au-dessus d'une rivière ou d'un lac peuvent recevoir la lumière réfléchie par l'eau. L'exposition vers l'équateur maximise la lumière, surtout près des pôles.",
   "Without light there is no photosynthesis: more light means more glucose for growth and ripening, and better flowering and fruit set. The further from the Equator, the longer the summer days: this helps Riesling ripen in Germany. Near seas and lakes there is more cloud, but vineyards above a river or lake can benefit from sunlight reflected off the water. Facing the Equator maximises light, especially closest to the Poles."),
  v:()=>fSvg(fSun(60,36,16)+`<path d="M0 200V120Q160 110 320 130V200Z" fill="#3b7fa8"/><path d="M150 120L320 40V130Z" fill="#6b7a3a"/>`+fRows(170,112,310,50,8)+fRays(60,36,[[240,80],[200,124]])+fD(1,`<path d="M200 124L250 70" stroke="#f8cf5f" stroke-width="1.8" stroke-dasharray="4 4"><animate attributeName="stroke-dashoffset" from="16" to="0" dur=".8s" repeatCount="indefinite"/></path>`)+fChip(110,170,w3("luce riflessa dall'acqua","lumière réfléchie par l'eau","light reflected off water")),"summer")},
 {h:I3("I rischi legati alla luce","Les risques liés à la lumière","Sunlight hazards"),
  c:I3("Il cielo coperto durante la fioritura riduce il raccolto, e nuvole persistenti rallentano la fotosintesi impedendo all'uva di maturare del tutto. All'opposto, un sole troppo intenso può scottare gli acini, con sapori amari nelle bucce. Il viticoltore gestisce la chioma per massimizzare la luce nelle zone nuvolose o per fare ombra nelle zone molto soleggiate.",
   "Un ciel couvert pendant la floraison réduit la récolte, et des nuages persistants ralentissent la photosynthèse et empêchent le raisin de mûrir complètement. À l'inverse, un soleil trop intense peut brûler les baies, avec des goûts amers dans les peaux. Le viticulteur gère le feuillage pour maximiser la lumière dans les zones nuageuses ou faire de l'ombre dans les zones très ensoleillées.",
   "Cloudy weather at flowering reduces the crop, and heavy cloud cover slows photosynthesis and stops grapes ripening fully. At the other extreme, intense sunshine can cause sunburn, with bitter flavours in the skins. The grower manages the canopy to maximise light in cloudy areas or provide shade in very sunny ones."),
  v:()=>`<svg class="fsvg" viewBox="0 0 320 200" aria-hidden="true">${fDefs}<rect width="160" height="200" fill="#aab3bd"/><rect x="160" width="160" height="200" fill="#ffd27a"/>${fCloud(80,40,1.6,"#7d8590",10)}${fSun(250,40,18)}${fGround()}${fBunch(80,110,2,"#9cc65a")}${fBunch(240,110,2,"#7a4a2a")}${fChip(80,180,w3("poca maturazione","maturité insuffisante","poor ripening"))}${fChip(240,180,w3("scottature","échaudage","sunburn"))}</svg>`}
]},
{id:"env2",sec:"v",ch:"env",ic:"maps",t:I3("L'ambiente: acqua, clima e suolo","L'environnement : eau, climat et sol","The environment: water, climate and soil"),s:[
 {h:I3("L'acqua","L'eau","Water"),
  c:I3("La vite usa l'acqua per la fotosintesi e per gonfiare gli acini. La assorbe con le radici e la porta alle foglie: è la traspirazione. Più fa caldo, più acqua evapora dalle foglie e più la vite deve assorbirne. Quando la chioma è ormai sviluppata, limitare un po' l'acqua è utile: la vite continua la fotosintesi ma smette di allungare i germogli e si concentra sull'uva, con meno ombra.",
   "La vigne utilise l'eau pour la photosynthèse et pour gonfler les baies. Elle l'absorbe par les racines et la conduit aux feuilles : c'est la transpiration. Plus il fait chaud, plus l'eau s'évapore des feuilles et plus la vigne doit en absorber. Une fois le feuillage développé, limiter un peu l'eau est utile : la vigne continue la photosynthèse mais cesse d'allonger ses rameaux et se concentre sur le raisin, avec moins d'ombre.",
   "The vine uses water for photosynthesis and to swell its grapes. It takes it up through the roots and draws it to the leaves: this is transpiration. The hotter it is, the more water evaporates from the leaves and the more the vine must absorb. Once the canopy has grown, limiting water a little is helpful: the vine keeps photosynthesising but stops growing shoots and concentrates on the grapes, with less shading."),
  v:()=>fSvg(fSun(280,36,14)+fGround()+vForm("headspur","canopy",160,172)+fRoots(160,174)+[0,1,2,3].map(i=>`<circle r="2.4" fill="#7fc7ec"><animateMotion dur="2.4s" begin="${i*.6}s" repeatCount="indefinite" path="M160 196V140L${130+i*20} 100"/></circle>`).join("")+fD(1.5,[0,1,2].map(i=>`<path d="M${120+i*30} 90q4 -10 0 -18" stroke="#bfe3f5" stroke-width="1.6" fill="none"><animate attributeName="opacity" values="0;1;0" dur="1.8s" begin="${i*.4}s" repeatCount="indefinite"/></path>`).join(""))+fChip(60,40,w3("traspirazione","transpiration","transpiration")),"summer")},
 {h:I3("L'irrigazione","L'irrigation","Irrigation"),
  c:I3("La fonte principale d'acqua è la pioggia; se non basta, dove la legge lo consente si irriga. L'irrigazione a goccia è la più avanzata e costosa: ogni vite ha il suo gocciolatore, anche controllato dal computer. Gli irrigatori a pioggia costano meno ma sprecano acqua e creano umidità, che favorisce le malattie; servono anche contro il gelo. L'irrigazione per sommersione costa pochissimo, ma richiede terreni pianeggianti e molta acqua.",
   "La principale source d'eau est la pluie ; si elle ne suffit pas, on irrigue là où la loi le permet. Le goutte-à-goutte est le plus avancé et le plus cher : chaque pied a son goutteur, parfois piloté par ordinateur. Les asperseurs coûtent moins mais gaspillent l'eau et créent de l'humidité, qui favorise les maladies ; ils servent aussi contre le gel. L'irrigation par submersion coûte très peu, mais exige des terrains plats et beaucoup d'eau.",
   "Rain is the main source of water; if it is not enough, vines are irrigated where local laws allow. Drip irrigation is the most advanced and expensive: each vine has its own dripper, which can be computer-controlled. Sprinklers are cheaper but waste water and create damp conditions that encourage disease; they can also protect against frost. Flood irrigation is very cheap but needs flat land and large quantities of water."),
  v:()=>fSvg(fGround()+[60,160,260].map(x=>vForm("bush","canopy",x,170)).join("")+`<path d="M20 172H120" stroke="#2b2b2b" stroke-width="3"/>`+[40,60,80,100].map(x=>fDrops(x,174,190,"#7fc7ec",2)).join("")+fSprinkler(160,172)+fD(.5,`<rect x="210" y="172" width="100" height="10" fill="#7fc7ec" opacity=".7"><animate attributeName="width" from="0" to="100" dur="2s" fill="freeze"/></rect>`)+fChip(70,26,w3("goccia","goutte-à-goutte","drip"))+fChip(160,26,w3("a pioggia","aspersion","sprinklers"))+fChip(260,26,w3("sommersione","submersion","flood")),"summer")},
 {h:I3("Siccità e acqua in eccesso","Sécheresse et excès d'eau","Drought and too much water"),
  c:I3("Con poca acqua la vite può sospendere la traspirazione; se la carenza dura, va in stress idrico: la fotosintesi si ferma, le foglie appassiscono e l'uva non matura, fino a indebolire e uccidere la pianta. Con troppa acqua, invece, la vite continua a produrre germogli e foglie, toglie zucchero all'uva e fa più ombra; un terreno saturo può far morire le radici. Si evita piantando in pendio o con tubi di drenaggio.",
   "Avec peu d'eau la vigne peut suspendre la transpiration ; si le manque dure, elle subit un stress hydrique : la photosynthèse s'arrête, les feuilles flétrissent et le raisin ne mûrit pas, jusqu'à affaiblir et tuer la plante. Avec trop d'eau, au contraire, la vigne continue à produire rameaux et feuilles, prive le raisin de sucre et fait plus d'ombre ; un sol gorgé d'eau peut faire mourir les racines. On l'évite en plantant en pente ou avec des drains.",
   "With little water the vine can temporarily stop transpiring; if the shortage lasts it suffers water stress: photosynthesis stops, leaves wilt and grapes fail to ripen, eventually weakening and killing the vine. With too much water, by contrast, the vine keeps growing shoots and leaves, diverting sugar from the grapes and adding shade; waterlogged soil can kill the roots. This is avoided by planting on slopes or installing drainage pipes."),
  v:()=>`<svg class="fsvg" viewBox="0 0 320 200" aria-hidden="true">${fDefs}<rect width="160" height="200" fill="#ffd27a"/><rect x="160" width="160" height="200" fill="#9fb3c8"/>${fGround("#b08a5a")}<path d="M20 182l14 6 8-8 12 10" stroke="#7a5a3c" fill="none"/>${vForm("bush","bare",80,170)}${vForm("bush","canopy",240,170)}<rect x="170" y="176" width="150" height="24" fill="#4a7fa8" opacity=".6"/><path d="M180 194H310" stroke="#5c646b" stroke-width="5" stroke-dasharray="10 4"/>${fChip(80,26,w3("stress idrico","stress hydrique","water stress"))}${fChip(240,26,w3("troppa vegetazione, drenaggio","trop de végétation, drainage","too much growth, drainage"))}</svg>`},
 {h:I3("La pioggia: quando e quanta","La pluie : quand et combien","Rain: timing and amount"),
  c:I3("Conta sia quanta pioggia cade sia quando. Piogge forti durante fioritura e allegagione riducono gli acini che si formano; l'umidità che segue favorisce le malattie fungine. La pioggia poco prima della vendemmia gonfia gli acini, diluisce i sapori e nei casi estremi li fa spaccare, aprendo la strada ai funghi.",
   "Comptent à la fois la quantité de pluie et le moment où elle tombe. De fortes pluies pendant la floraison et la nouaison réduisent le nombre de baies ; l'humidité qui suit favorise les maladies fongiques. La pluie juste avant les vendanges fait gonfler les baies, dilue les arômes et, dans les cas extrêmes, les fait éclater, ouvrant la porte aux champignons.",
   "Both the amount of rain and its timing matter. Heavy rain at flowering and fruit set reduces the number of grapes formed; the damp that follows encourages fungal disease. Rain shortly before harvest swells the berries, dilutes the flavours and in extreme cases splits them, inviting fungal infection."),
  v:()=>fSvg(fCloud(160,30,2,"#6b7280",10)+Array.from({length:22},(_,i)=>`<path d="M${10+i*14} 40l-3 8" stroke="#bfe3f5" stroke-width="1.4"><animateTransform attributeName="transform" type="translate" from="0 0" to="-12 150" dur="${.7+(i%4)*.15}s" begin="${-(i*.1)}s" repeatCount="indefinite"/></path>`).join("")+fGround()+fVine("ripe")+fD(2,`<circle cx="270" cy="150" r="14" fill="#6b2d5c"/><path d="M262 142l16 16" stroke="#f3e3c3" stroke-width="2"/>`+fChip(270,182,w3("acino spaccato","baie éclatée","split berry"))),"autumn")},
 {h:I3("La grandine","La grêle","Hail"),
  c:I3("La grandine danneggia l'uva e anche la pianta, e nei casi peggiori distrugge l'intero raccolto. Alcune zone, come Mendoza in Argentina, ne sono particolarmente colpite. Le reti antigrandine proteggono ma sono costose. Poiché le grandinate sono molto localizzate, la migliore assicurazione può essere avere vigneti in luoghi diversi.",
   "La grêle abîme le raisin et même la plante, et dans les pires cas détruit toute la récolte. Certaines zones, comme Mendoza en Argentine, y sont particulièrement exposées. Les filets paragrêle protègent mais coûtent cher. Les orages de grêle étant très localisés, la meilleure assurance peut être de posséder des vignes en plusieurs endroits.",
   "Hail damages grapes and even the vine itself, and in the worst cases destroys the entire crop. Some areas, such as Mendoza in Argentina, are particularly prone to it. Netting protects the vines but is costly. Because hailstorms are very localised, the best insurance may be to own vineyards in several different places."),
  v:()=>fSvg(fCloud(90,34,1.6,"#5b6270",12)+fCloud(220,30,1.8,"#4b5260",14)+fGround()+fVine("set")+fD(1.5,fNet(56,46,208,126))+Array.from({length:18},(_,i)=>`<circle cx="${20+i*17}" cy="40" r="2.4" fill="#eef4fb"><animate attributeName="cy" from="40" to="${i%3?46:170}" dur="${.9+(i%4)*.2}s" begin="${-(i*.13)}s" repeatCount="indefinite"/></circle>`).join("")+fChip(160,190,"Mendoza"),"winter")},
 {h:I3("Clima e andamento dell'annata","Climat et millésime","Climate and weather"),
  c:I3("Il clima di una regione è l'andamento medio di temperatura, luce e pioggia su più anni: non cambia da un anno all'altro, ma può cambiare nei decenni. Il tempo, o andamento stagionale, è la variazione di ogni singolo anno rispetto alla media. A Bordeaux varia molto: il 2007 fu fresco, nuvoloso e piovoso ad agosto, il 2003 caldissimo e quasi siccitoso. Nella Central Valley californiana, invece, il tempo è caldo e secco quasi ogni anno.",
   "Le climat d'une région est le profil moyen de température, de lumière et de pluie sur plusieurs années : il ne change pas d'une année à l'autre, mais peut évoluer sur des décennies. La météo, c'est la variation de chaque année par rapport à la moyenne. À Bordeaux elle varie beaucoup : 2007 fut frais, nuageux et pluvieux en août, 2003 très chaud et presque sec. Dans la Central Valley californienne, au contraire, le temps est chaud et sec presque chaque année.",
   "A region's climate is the average annual pattern of temperature, sunlight and rainfall over several years: it does not change from one year to the next, though it can over decades. Weather is each year's variation from that average. In Bordeaux it varies a lot: 2007 was cool, cloudy and wet in August, while 2003 was very hot with near-drought. In California's Central Valley, by contrast, the weather is hot and dry almost every year."),
  v:()=>fSvg(fBox(20,24,130,30,"Bordeaux 2007",{fill:"rgba(79,168,162,.5)"})+fCloud(85,90,1.3,"#9aa3ab")+fBox(170,24,130,30,"Bordeaux 2003",{fill:"rgba(181,51,74,.55)"})+fSun(235,90,16)+fD(1.5,fBox(60,140,200,34,w3("Central Valley: caldo e secco ogni anno","Central Valley : chaud et sec chaque année","Central Valley: hot and dry every year"),{fill:"rgba(212,162,58,.35)"})))},
 {h:I3("Le classi di temperatura","Les classes de température","Temperature categories"),
  c:I3("Le regioni si classificano con la temperatura media della stagione vegetativa, da aprile a ottobre nell'emisfero nord e da ottobre ad aprile nel sud. Clima fresco: fino a 16,5 °C. Moderato: da 16,5 a 18,5 °C. Caldo: da 18,5 a 21 °C. Molto caldo: oltre 21 °C. Danno un'idea delle uve che possono maturare, ma vanno lette insieme a continentalità, escursione, pioggia e luce.",
   "On classe les régions selon la température moyenne de la saison de croissance, d'avril à octobre dans l'hémisphère nord et d'octobre à avril dans le sud. Climat frais : jusqu'à 16,5 °C. Modéré : de 16,5 à 18,5 °C. Chaud : de 18,5 à 21 °C. Très chaud : plus de 21 °C. Ces classes indiquent quels raisins peuvent mûrir, mais se lisent avec la continentalité, l'amplitude, la pluie et la lumière.",
   "Regions are classified by the average temperature of the growing season, April to October in the Northern Hemisphere and October to April in the Southern. Cool: 16.5 °C or below. Moderate: 16.5 to 18.5 °C. Warm: 18.5 to 21 °C. Hot: above 21 °C. These give a good guide to which grapes can ripen, but must be read together with continentality, diurnal range, rainfall and sunlight."),
  v:()=>fSvg(fTable([I3("Clima","Climat","Climate"),I3("Media stagione","Moyenne saison","Season average")],[[I3("Fresco","Frais","Cool"),"≤ 16,5 °C"],[I3("Moderato","Modéré","Moderate"),"16,5–18,5 °C"],[I3("Caldo","Chaud","Warm"),"18,5–21 °C"],[I3("Molto caldo","Très chaud","Hot"),"> 21 °C"]],[],{y:30,rh:30}))},
 {h:I3("Clima continentale","Climat continental","Continental climate"),
  c:I3("Grande differenza tra estate e inverno, estati brevi e un rapido calo di temperatura in autunno. I climi continentali freschi, come Chablis e Champagne, rischiano gelate primaverili, e il freddo può disturbare fioritura, allegagione e maturazione: sono adatti a varietà che germogliano tardi e maturano presto. Le estati sono spesso asciutte e, se fa caldo, può servire l'irrigazione.",
   "Grand écart entre été et hiver, étés courts et chute rapide de la température en automne. Les climats continentaux frais, comme Chablis et la Champagne, craignent les gelées de printemps, et le froid peut perturber floraison, nouaison et maturation : ils conviennent aux cépages à débourrement tardif et maturité précoce. Les étés sont souvent secs et, s'il fait chaud, l'irrigation peut être nécessaire.",
   "A big difference between summer and winter, short summers and a rapid temperature drop in autumn. Cool continental climates such as Chablis and Champagne are at risk from spring frost, and low temperatures can disrupt flowering, fruit set and ripening: they suit varieties that bud late and ripen early. Summers are often dry and, if hot, irrigation may be needed."),
  v:()=>fSvg(`<path d="M30 160Q80 160 110 60Q140 20 170 60Q200 160 290 160" stroke="#b5334a" stroke-width="4" fill="none" stroke-dasharray="400" stroke-dashoffset="400"><animate attributeName="stroke-dashoffset" from="400" to="0" dur="2.5s" fill="freeze"/></path><path d="M30 170H290" stroke="#7d6a70"/>`+fT(160,190,w3("gen → dic","janv → déc","Jan → Dec"),9)+fD(2,fChip(160,30,"Chablis · Champagne")))},
 {h:I3("Clima marittimo","Climat maritime","Maritime climate"),
  c:I3("Temperature da fresche a moderate e poca differenza tra estate e inverno. La pioggia è distribuita su tutto l'anno e modera le temperature, così l'uva può continuare a maturare fino a tardo autunno: per questo Bordeaux riesce a maturare il Cabernet Sauvignon, dalla buccia spessa. La pioggia in primavera ed estate può però disturbare la fioritura e la sanità dell'uva alla vendemmia.",
   "Températures fraîches à modérées et faible écart entre été et hiver. La pluie, répartie sur toute l'année, modère les températures, et le raisin peut continuer à mûrir jusqu'à tard en automne : c'est ainsi que Bordeaux parvient à mûrir le Cabernet Sauvignon, à peau épaisse. La pluie au printemps et en été peut toutefois nuire à la floraison et à l'état sanitaire du raisin aux vendanges.",
   "Cool to moderate temperatures and little difference between the hottest and coldest months. Rainfall is spread through the year and moderates temperatures, so grapes can keep ripening late into autumn: this is how maritime Bordeaux ripens thick-skinned Cabernet Sauvignon. Rain in spring and summer can, however, harm flowering and the health of the grapes at harvest."),
  v:()=>fSvg(`<path d="M30 120Q110 100 160 92Q210 100 290 120" stroke="#4fa8a2" stroke-width="4" fill="none"/><path d="M30 170H290" stroke="#7d6a70"/>`+Array.from({length:12},(_,i)=>`<rect x="${34+i*21}" y="${150-((i*7)%10)}" width="10" height="${20+((i*7)%10)}" fill="#7fc7ec" opacity=".8"/>`).join("")+fT(160,190,w3("pioggia tutto l'anno","pluie toute l'année","rain all year"),9)+fD(1.6,fChip(160,40,"Bordeaux · Cabernet Sauvignon")))},
 {h:I3("Clima mediterraneo","Climat méditerranéen","Mediterranean climate"),
  c:I3("Anche qui poca differenza tra estate e inverno, ma estati calde e asciutte. Lo si trova nel Mediterraneo e in gran parte della California costiera, del Cile, del Sudafrica e dell'Australia sud-orientale. Rispetto al clima marittimo, più calore e luce danno vini più corposi, con tannini più maturi, più alcol e meno acidità. La poca pioggia aiuta la sanità dell'uva ma può portare siccità.",
   "Ici aussi faible écart entre été et hiver, mais étés chauds et secs. On le trouve autour de la Méditerranée et dans une grande partie de la Californie côtière, du Chili, de l'Afrique du Sud et du sud-est de l'Australie. Par rapport au climat maritime, plus de chaleur et de lumière donnent des vins plus corsés, aux tanins plus mûrs, plus alcoolisés et moins acides. Le peu de pluie aide l'état sanitaire mais peut causer la sécheresse.",
   "Here too there is little difference between the hottest and coldest months, but summers are warm and dry. It is found around the Mediterranean and in much of coastal California, Chile, South Africa and south-eastern Australia. Compared with maritime climates, the extra warmth and sunlight give fuller-bodied wines with riper tannins, higher alcohol and lower acidity. Low rainfall helps grape health but can lead to drought."),
  v:()=>fSvg(fSun(60,40,16)+`<path d="M30 130Q110 90 160 76Q210 90 290 130" stroke="#d4a23a" stroke-width="4" fill="none"/><path d="M30 170H290" stroke="#7d6a70"/>`+fD(1,fBox(150,100,150,56,w3("più corpo e alcol, tannini maturi, meno acidità","plus de corps et d'alcool, tanins mûrs, moins d'acidité","fuller body, more alcohol, riper tannins, less acid"),{fill:"rgba(212,162,58,.3)"}))+fChip(90,186,w3("estate calda e secca","été chaud et sec","warm, dry summer")),"summer")},
 {h:I3("Com'è fatto il suolo","La composition du sol","Soil composition"),
  c:I3("Il suolo sta sopra la roccia madre e può essere spesso da pochi centimetri a diversi metri. È fatto di particelle di dimensioni diverse, di pietre e di humus. Le pietre sono le particelle più grandi e in superficie aiutano a scaldare il vigneto; tra le particelle fini, la sabbia è la più grande e l'argilla la più piccola. L'humus, materia organica in decomposizione, è ricco di nutrienti e trattiene bene l'acqua.",
   "Le sol repose sur la roche mère et son épaisseur va de quelques centimètres à plusieurs mètres. Il est fait de particules de tailles différentes, de cailloux et d'humus. Les cailloux sont les plus grosses particules et, en surface, aident à réchauffer la vigne ; parmi les particules fines, le sable est la plus grosse et l'argile la plus petite. L'humus, matière organique en décomposition, est riche en nutriments et retient bien l'eau.",
   "Soil sits above the bedrock and may be anything from a few centimetres to several metres deep. It is made of particles of various sizes, plus stones and humus. Stones are the largest and, on the surface, help warm the vineyard; among the fine particles, sand is the largest and clay the smallest. Humus, decomposing organic matter, is rich in nutrients and holds water well."),
  v:()=>fSvg(fSoil(40,16,170,180,[{f:.12,c:"#5a3e2a",k:"humus",lab:I3("humus","humus","humus")},{f:.18,c:"#8a7d6b",k:"stone",lab:I3("pietre","cailloux","stones")},{f:.22,c:"#d8b878",k:"sand",lab:I3("sabbia","sable","sand")},{f:.22,c:"#b06a44",k:"clay",lab:I3("argilla","argile","clay")},{f:.26,c:"#6e6a66",lab:I3("roccia madre","roche mère","bedrock")}])+fRoots(120,20))},
 {h:I3("Suolo e acqua","Sol et eau","Soil and water"),
  c:I3("L'acqua resta nel suolo legandosi all'argilla e all'humus. Troppa argilla rende il suolo facilmente saturo, fino a far morire le radici; sabbia e pietre invece trattengono poco e drenano. Molti dei suoli migliori sono un misto di sabbia e argilla, il franco: drena bene ma trattiene abbastanza acqua. L'ideale è acqua in abbondanza a inizio stagione e un leggero stress idrico dopo l'invaiatura, che favorisce la maturazione. Non esiste però un suolo ideale per tutti i climi.",
   "L'eau reste dans le sol en se liant à l'argile et à l'humus. Trop d'argile rend le sol facilement gorgé d'eau, jusqu'à faire mourir les racines ; le sable et les cailloux, au contraire, retiennent peu et drainent. Beaucoup des meilleurs sols sont un mélange de sable et d'argile, le limon (loam) : il draine bien mais retient assez d'eau. L'idéal est beaucoup d'eau en début de saison et un léger stress hydrique après la véraison, qui favorise la maturation. Il n'existe toutefois pas de sol idéal pour tous les climats.",
   "Water is held in the soil by binding to clay particles and humus. Too much clay makes soil easily waterlogged, which can kill the roots; sand and stones hold little water and drain freely. Many of the best soils are a mix of sand and clay, loam: it drains well but retains enough water. Ideally the vine has plenty of water early in the season and mild water stress after véraison, which promotes ripening. No single soil is ideal for every climate, though."),
  v:()=>fSvg([[20,"#b06a44",I3("argilla: trattiene","argile : retient","clay: holds water"),.9],[120,"#c79a5c",I3("franco: equilibrio","limon : équilibre","loam: balance"),.5],[220,"#d8b878",I3("sabbia: drena","sable : draine","sand: drains"),.15]].map(([x,c,l,f],i)=>`<rect x="${x}" y="60" width="80" height="110" fill="${c}"/><rect x="${x}" y="${170-110*f}" width="80" height="${110*f}" fill="#4a7fa8" opacity=".55"><animate attributeName="height" from="0" to="${110*f}" dur="2s" begin="${i*.4}s" fill="freeze"/><animate attributeName="y" from="170" to="${170-110*f}" dur="2s" begin="${i*.4}s" fill="freeze"/></rect>`+fT(x+40,190,tx(l),8.5)).join("")+fChip(160,30,w3("acqua trattenuta","eau retenue","water retained")))},
 {h:I3("Suolo e nutrienti","Sol et nutriments","Soil and nutrients"),
  c:I3("I nutrienti più importanti sono azoto, fosforo e potassio, presenti nel suolo e assorbiti dalle radici. La vite non ne ha bisogno in grandi quantità: troppi nutrienti la rendono troppo vigorosa, con una chioma fitta che ombreggia l'uva. Col tempo però il suolo si impoverisce e si reintegra con concimi naturali o chimici. Un sintomo tipico di carenza è la clorosi: le foglie ingialliscono, la fotosintesi cala e l'uva matura male.",
   "Les nutriments les plus importants sont l'azote, le phosphore et le potassium, présents dans le sol et absorbés par les racines. La vigne n'en a pas besoin en grande quantité : trop de nutriments la rendent trop vigoureuse, avec un feuillage dense qui ombrage le raisin. Avec le temps, le sol s'appauvrit et on le complète avec des engrais naturels ou chimiques. Un symptôme typique de carence est la chlorose : les feuilles jaunissent, la photosynthèse baisse et le raisin mûrit mal.",
   "The most important nutrients are nitrogen, phosphorus and potassium, present in the soil and taken up by the roots. Vines do not need high levels: too many nutrients make them grow too vigorously, with a dense canopy that shades the fruit. Over time, though, soil becomes depleted and is replenished with natural or chemical fertilisers. A common sign of deficiency is chlorosis: leaves turn yellow, photosynthesis is restricted and grapes ripen poorly."),
  v:()=>fSvg(fGround()+[["N",70],["P",110],["K",150]].map(([n,x],i)=>fD(i*.3,`<circle cx="${x}" cy="186" r="9" fill="#5e8c31"/>`+fT(x,190,n,10))).join("")+`<g transform="translate(240 120)">${fLeaf(0,0,2.6,0,"#5e8c31")}<path d="M0 0C-9-3-13-14-6-21" fill="none"/></g>`+fD(1.8,`<g transform="translate(240 120)">${fLeaf(0,0,2.6,0,"#d9c24a")}</g>`+fChip(240,170,w3("clorosi","chlorose","chlorosis"),"#a87b1e")),"summer")}
]}
);
